mapper.select:
SELECT  FROM rpa_database.inventory_snapshot
WHERE source_key = #{query.sourceKey}
AND period = #{query.period}
AND excluded = #{query.excluded}

    AND COALESCE(source_sheet, '') = #{query.sourceSheet}
    AND COALESCE(raw_warehouse, '') = #{query.rawWarehouse}
    AND COALESCE(platform, '') = #{query.platform}
    AND COALESCE(platform_scope, '') = #{query.platformScope}
    AND COALESCE(country, '') = #{query.country}
    AND COALESCE(market_scope, '') = #{query.marketScope}
    AND COALESCE(warehouse, '') = #{query.warehouse}
    AND COALESCE(warehouse_country, '') = #{query.warehouseCountry}
    AND COALESCE(shop, '') = #{query.shop}
    AND COALESCE(local_sku, '') = #{query.localSku}
    AND COALESCE(platform_sku, '') = #{query.platformSku}
    AND COALESCE(quantity_basis, '') = #{query.quantityBasis}
    AND COALESCE(currency, '') = #{query.currency}

ORDER BY period, source_sheet, source_row, id
